import re
from decimal import Decimal

MAX_AMOUNT = Decimal("1000000.00")
_PLAIN_DECIMAL = re.compile(r"[+-]?[0-9]+(?:\.[0-9]+)?")
_CENT = -2


def parse_amount(value):
    """Return a positive Decimal (exponent -2) of at most 1000000.00.

    Accepts Decimal, int (not bool) and plain decimal strings. Raises
    ValueError for anything else or for values not exactly in cents.
    Uses only exact arithmetic, so the decimal context is never touched.
    """
    if isinstance(value, bool):
        raise ValueError("invalid amount type")
    if isinstance(value, Decimal):
        number = value
    elif isinstance(value, int):
        number = Decimal(value)
    elif isinstance(value, str):
        if _PLAIN_DECIMAL.fullmatch(value) is None:
            raise ValueError("invalid amount string")
        number = Decimal(value)
    else:
        raise ValueError("invalid amount type")

    if not number.is_finite():
        raise ValueError("amount must be finite")
    if number <= 0:
        raise ValueError("amount must be positive")
    if number > MAX_AMOUNT:
        raise ValueError("amount too large")

    _, digits, exponent = number.as_tuple()
    if exponent < _CENT:
        drop = _CENT - exponent
        trailing_zeros = len(digits) - len(digits.rstrip_zeros()) if False else 0
        for d in reversed(digits):
            if d != 0:
                break
            trailing_zeros += 1
        if drop > trailing_zeros:
            raise ValueError("amount not representable in cents")
        digits = digits[:len(digits) - drop]
    elif exponent > _CENT:
        digits = digits + (0,) * (exponent - _CENT)
    return Decimal((0, digits, _CENT))


def format_amount(value):
    return format(value, ".2f")
